import assert from 'node:assert/strict';
import test from 'node:test';
import {
  BUILD_INTERNAL_PATHS,
  EXHIBITION_HEADER_BLOCK,
  deployFlag,
  isBuildInternal,
  partitionPublishable,
  withExhibitionHeaders,
} from './pages-publish.ts';

/** The generated file, verbatim, as vinext writes it. */
const generated = `# Cache content-hashed assets immutably (generated by vinext)
/_next/static/*
  Cache-Control: public, max-age=31536000, immutable
`;

void test('build bookkeeping is withheld and the room is published', () => {
  const { publish, withhold } = partitionPublishable([
    'index.html',
    '404.html',
    '_headers',
    'favicon.svg',
    'index.rsc',
    '_next/static/chunks/room-installation-sOKwz-YE.js',
    'voice/mirror-0.wav',
    'audio/capture-worklet.js',
    '.assetsignore',
    '.vite/manifest.json',
    'vinext-client-entry-manifest.json',
  ]);
  assert.deepEqual(withhold, [
    '.assetsignore',
    '.vite/manifest.json',
    'vinext-client-entry-manifest.json',
  ]);
  // The room's own files survive: markup, the voice, and the capture worklet.
  assert.ok(publish.includes('index.html'));
  assert.ok(publish.includes('voice/mirror-0.wav'));
  assert.ok(publish.includes('audio/capture-worklet.js'));
  assert.equal(publish.length, 8);
});

void test('a directory is withheld by naming the directory', () => {
  // The point of prefix matching: a second file appearing in .vite needs no
  // new entry, and the publish step does not start serving it silently.
  assert.equal(isBuildInternal('.vite'), true);
  assert.equal(isBuildInternal('.vite/manifest.json'), true);
  assert.equal(isBuildInternal('.vite/deps/something-new.json'), true);
  assert.equal(isBuildInternal('./.vite/manifest.json'), true);
  assert.equal(isBuildInternal('.vite\\manifest.json'), true);
});

void test('a name that merely starts the same is still the room', () => {
  // `.assetsignore` is withheld; `.assetsignore-notes` was never the rule.
  assert.equal(isBuildInternal('.assetsignore-notes'), false);
  assert.equal(isBuildInternal('.vitest.json'), false);
  assert.equal(isBuildInternal('voice/.vite-sounding.wav'), false);
});

void test('every withheld path is one the artifact actually contains', () => {
  // Guards the list against drift into names that no build ever produces.
  for (const internal of BUILD_INTERNAL_PATHS) {
    assert.equal(isBuildInternal(internal), true);
  }
});

void test('the device policy is added to the generated headers', () => {
  const published = withExhibitionHeaders(generated);
  // The caching the build chose is preserved, not replaced.
  assert.match(published, /Cache-Control: public, max-age=31536000, immutable/);
  assert.match(published, /Permissions-Policy: camera=\(self\), microphone=\(self\)/);
  assert.ok(published.startsWith(generated));
  assert.ok(published.endsWith(EXHIBITION_HEADER_BLOCK));
});

void test('publishing twice does not write the policy twice', () => {
  const once = withExhibitionHeaders(generated);
  const twice = withExhibitionHeaders(once);
  assert.equal(twice, once);
  assert.equal(twice.match(/Permissions-Policy:/g)?.length, 1);
});

void test('headers without a trailing newline still parse as two sections', () => {
  const unterminated = generated.trimEnd();
  const published = withExhibitionHeaders(unterminated);
  // A rule and the next section's path must not end up on one line.
  assert.match(published, /immutable\n\n#/);
  assert.equal(published.includes('immutable#'), false);
});

/** argv as Node hands it over: the executable and the script come first. */
const argv = (...flags: string[]) => ['/usr/bin/node', 'scripts/deploy-pages.mjs', ...flags];

void test('a flag that is absent falls back', () => {
  assert.equal(deployFlag(argv(), 'project', 'the-room-remembers-you'), 'the-room-remembers-you');
  assert.equal(deployFlag(argv('--dry-run'), 'branch', 'main'), 'main');
});

void test('a flag that is given is read', () => {
  assert.equal(deployFlag(argv('--project=other-room'), 'project', 'fallback'), 'other-room');
  assert.equal(deployFlag(argv('--dry-run', '--branch=preview'), 'branch', 'main'), 'preview');
});

void test('an empty flag falls back rather than publishing to nothing', () => {
  // `--project=` would otherwise hand wrangler `--project-name=` and the error
  // that comes back describes argument parsing, not the empty flag behind it.
  assert.equal(deployFlag(argv('--project='), 'project', 'the-room-remembers-you'), 'the-room-remembers-you');
});

void test('a longer flag name is not mistaken for a shorter one', () => {
  // `--project-name=` is wrangler's own spelling and sits next to ours in the
  // shell history; reading it as `project` would publish somewhere unintended.
  assert.equal(deployFlag(argv('--project-name=wrangler-spelling'), 'project', 'ours'), 'ours');
});

void test('a value may contain the separator', () => {
  assert.equal(deployFlag(argv('--branch=feature=thing'), 'branch', 'main'), 'feature=thing');
});

void test('the first occurrence of a repeated flag wins', () => {
  assert.equal(deployFlag(argv('--branch=first', '--branch=second'), 'branch', 'main'), 'first');
});
